# Generated by build.py from recipe.yml for recipe http-find-the-client-that-misbehaved. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'who-sent-it.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# For each request surl answered 400 in the trace file `$1: the connection (exchange) it came on,`n# the client's address and port, surl's reason, and the request head as received.`nawk '`n  { sub(/\r`$/, `"`") }`n  /^#[0-9]+ / { n = substr(`$1, 2); recv = (`$2 == `"<=`") }`n  /^#[0-9]+ \* Exchange [0-9]+ opened: / { from[n] = `$NF; sub(/\.`$/, `"`", from[n]) }`n  recv && /^[0-9a-f]+: [A-Z]+ [^ ]+ HTTP\/1\.[01]`$/ { head[n] = `"`" }`n  recv && /^[0-9a-f]+: ./ { head[n] = head[n] `"  `" substr(`$0, 7) `"\n`" }`n  /^#[0-9]+ \* .*answered 400/ {`n    why = `$0; sub(/^#[0-9]+ \* /, `"`", why); sub(/; answered 400.*/, `"`", why)`n    bad[++count] = n; reason[n] = why`n  }`n  END {`n    for (i = 1; i <= count; i++) { n = bad[i]; printf `"exchange %s from %s: %s\n%s`", n, from[n], reason[n], head[n] }`n    if (count == 0) print `"no request was answered 400`"`n  }`n' `"`$1`"`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--trace-ascii', 'trace.txt', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh who-sent-it.sh trace.txt } finally { Stop-Process $server0 }
